 test("void reasons scenario 2", { tag: '@functionality' }, async ({ browser }) => {
   const sheet = ui.sheetId();
   const pg_uma = await ui.userPage(browser, "uma", sheet);
   await ui.setToday(pg_uma, "2026-03-20");
   await ui.setSetting(pg_uma, "clerk-limit", "3.00");
   await ui.setSetting(pg_uma, "policy-date", "2026-03-15");
   await ui.setSetting(pg_uma, "period-numbering-from", "2026-03-01");
   await ui.setSetting(pg_uma, "terms-C", "20");
   expect(await ui.setRole(pg_uma, "vic", "viewer")).toBe(true);
   await ui.setSetting(pg_uma, "grace-days", "0");
   expect(await ui.addHoliday(pg_uma, "2026-03-24")).toBe(true);
   expect(await ui.addVoidReason(pg_uma, "late")).toBe(true);
   expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "33.33"})).toBe(true);
   expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "20.00"})).toBe(true);
   expect(await ui.addPeriod(pg_uma, {"name": "P1", "from": "2026-03-01", "to": "2026-03-15"})).toBe(true);
   const p_cam = ui.must(await ui.addPerson(pg_uma, {"name": "Cam", "grade": "B"}));
   const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "B", "terms": "20"}));
   expect(await ui.periodAction(pg_uma, "P1", "soft-close")).toBe(true);
   expect(await ui.addPatron(pg_uma, p_ada, "Cam")).toBe(true);
   const c_ada_0 = ui.must(await ui.addClaim(pg_uma, p_ada, {"amount": "7.77", "date": "2026-03-05", "note": "n", "tags": " c "}));
   expect(await ui.bulkGrade(pg_uma, [p_cam, p_ada], {"grade": "B", "from": "2026-02-10"})).toBe(2);
   const c_ada_1 = ui.must(await ui.addClaim(pg_uma, p_ada, {"amount": "10.25", "tags": "a"}));
   const c_ada_2 = ui.must(await ui.addClaim(pg_uma, p_ada, {"amount": "99.95", "note": "n", "ref": "inv 7"}));
   expect(await ui.editPerson(pg_uma, p_ada, {"grade": "B", "gradeFrom": "2026-03-09"})).toBe(true);
   await ui.refresh(pg_uma);
   await expect(pg_uma.getByTestId("person-row-" + p_cam).getByTestId("person-claimed")).toHaveText("0.00");
   await expect(pg_uma.getByTestId("person-row-" + p_cam).getByTestId("person-due-total")).toHaveText("0.00");
   await expect(pg_uma.getByTestId("person-row-" + p_ada).getByTestId("person-claimed")).toHaveText("0.00");
