  template: `
    @if (session.user(); as user) {
      <p>Signed in as <strong data-testid="current-user">{{ user }}</strong></p>
      <form (submit)="load($event)">
        <label for="sheet-id">Sheet id</label>
        <input
          id="sheet-id"
          data-testid="sheet-id-input"
          [value]="sheetId()"
          (input)="sheetId.set(value($event)); sheetError.set(null)"
        />
        <button type="submit" data-testid="sheet-load">Load</button>
        @if (sheetError(); as error) {
          <p role="alert" data-testid="sheet-error">{{ error }}</p>
        }
      </form>
      @if (session.sheet(); as sheet) {
        <p>Sheet <strong data-testid="sheet-current-id">{{ sheet }}</strong></p>
        <p>Today <strong data-testid="sheet-today">{{ session.today() }}</strong></p>
        <form (submit)="saveToday($event)">
          <label for="sheet-today-input">Change today</label>
          <input
            id="sheet-today-input"
            type="date"
            data-testid="sheet-today-input"
            [value]="todayInput()"
            (input)="todayInput.set(value($event)); sheetError.set(null)"
          />
          <button type="submit" data-testid="sheet-today-save">Set today</button>
        </form>
        <form (submit)="setAsOf($event)">
          <label for="asof-date">Show as of</label>
          <input
            id="asof-date"
            type="date"
            data-testid="asof-date"
            [value]="asOfInput()"
            (input)="asOfInput.set(value($event)); asOfError.set(null)"
          />
          <button type="submit" data-testid="asof-set">Set as of</button>
          <button type="button" data-testid="asof-clear" (click)="clearAsOf()">Clear as of</button>
          @if (asOfError(); as error) {
            <p role="alert" data-testid="asof-error">{{ error }}</p>
          }
        </form>
        <p>As of <strong data-testid="sheet-asof">{{ session.asOf() ?? '' }}</strong></p>
        <p>Archived <strong data-testid="sheet-archived">{{ session.archived() ? 'yes' : 'no' }}</strong></p>
        <button type="button" data-testid="sheet-archive" (click)="archive()">Archive sheet</button>
        <app-settings />
        <app-holidays />
        <app-people />
      }
    } @else {
      <form (submit)="signIn($event)">
        <label for="signin-name">Name</label>
        <input
          id="signin-name"
          data-testid="signin-name"
          [value]="name()"
          (input)="name.set(value($event)); signinError.set(null)"
  protected readonly tags = signal<string[]>([]);
  /**
   * Per tag ever used on the sheet: the dues of the claims that count in the live totals and carry it, skipping the
   * n/a ones (a claim with two tags counts in both).
   */
  protected readonly tagTotals = computed(() =>
    this.tags().map((tag) => ({
      tag,
      dueTotal: sumDues(this.people().map((p) => this.liveDuesOf(p, (c) => tagsOf(c).includes(tag)))),
    })),
  );
  /** Per grade: the people not retired on it today, as the list shows their grade, and their due-totals added up. */
  protected readonly gradeSummary = computed<GradeSummary[]>(() =>
    this.grades.map((grade) => {
      const on = this.people().filter((p) => !p.retired && this.gradeOf(p) === grade);
      return {
        grade,
        count: on.length,
        dueTotal: sumDues(on.map((p) => this.dueTotalOf(p))),
        active: on.filter((p) => this.isActive(p)).length,
      };
    }),
  );
  /** Per period: its due-total as the period list shows it. */
  protected readonly periodSummary = computed<PeriodSummary[]>(() =>
    this.periods().map((p) => ({
      name: p.name,
      dueTotal: p.closedTotal ?? this.periodDueTotals().get(p.name) ?? '0.00',
    })),
  );
  /** Per status: how many of the sheet's claims have it. */
  protected readonly statusSummary = computed<StatusSummary[]>(() =>
    ['DRAFT', 'OPEN', 'PENDING', 'SETTLED', 'VOID'].map((status) => ({
      status,
      count: this.claims().filter((c) => c.status === status).length,
    })),
  );
  protected readonly name = signal('');
  protected readonly grade = signal('A');
  /** The date the form's grade applies from; blank for the sheet's today. */
  protected readonly gradeFrom = signal('');
  /** The person's own terms in whole days; blank for none. */
  protected readonly terms = signal('');
  /** The id of the person whose editor is open, or null when the form adds a person. */
  protected readonly editing = signal<number | null>(null);
  /** The version of the person the editor loaded. */
  private editingVersion = 0;
  /** Whether a submit is waiting for its answer: a second submit meanwhile is ignored. */
  private submitting = false;
  protected readonly error = signal<string | null>(null);
  /** The quick-add bar: a name and an amount, and the error of its last refused submit. */
  protected readonly quickName = signal('');
  protected readonly quickAmount = signal('');
  protected readonly quickError = signal<string | null>(null);
  private quickAdding = false;
  /** The paste box: its lines, how many its last paste added (null while it runs and before the first), its error. */
  protected readonly pasteText = signal('');
  protected readonly pasteAdded = signal<number | null>(null);
  protected readonly pasteError = signal<string | null>(null);
  private pasting = false;
  /** The error of the last action on a person's row that was refused, and the person it belongs to. */
